/**
 * Vizag With You — Full Hero Section Interactive 3D Background
 * Features:
 * - Full-Viewport Background Canvas: Stretches across the entire .hero-viewport background.
 * - Cute, Vibrant Red Blood-Drop Mascot:
 *     Glossy clearcoat, white medical headband, heart badge, rosy cheeks, cheek bandaid,
 *     large glossy cartoon eyes with shiny reflection highlights, and realistic bipedal walking physics.
 * - Less Shiny Heart:
 *     Soft organic velvety/matte surface (roughness: 0.58, clearcoat: 0, no plastic shine).
 * - From Dull to Bright With Heart Beats:
 *     Dull & dormant initially (muted dark wine-red, 0 emissive glow, asleep).
 *     As the mascot presents the droplet, the heart transforms from dull to bright living red.
 *     With Heart Beats: Pumps with an authentic dual-phase "lub-dub" cardiac rhythm (~60 BPM),
 *     flashing bright surges of light with each systolic contraction and emitting soft red energy rings.
 * - Unrushed, realistic animation pacing (~24s natural story loop).
 */

(function () {
    let scene, camera, renderer, heroSection, sceneFrame;
    const mobileLayout = window.matchMedia('(max-width: 767px)');
    let limbs = [];
    let stageGroup, mascotGroup, mascotBodyMesh, leftFootMesh, rightFootMesh, leftHandMesh, rightHandMesh;
    let leftEyeGroup, rightEyeGroup;
    let leftEyePupil, rightEyePupil, leftHighlightMajor, leftHighlightMinor, rightHighlightMajor, rightHighlightMinor;
    let heldDropletGroup, heldDropletMesh, heldDropletHalo, heldDropletCore, heldDropletSparkle, heldDropletLight;
    let bigHeartGroup, bigHeartMesh, bigHeartInnerCore, bigHeartAura;
    let gatheringParticles = [], radiatingParticles = [], heartPulseWaves = [];
    let mascotShadowDisc, heartShadowDisc;

    // =========================================================================
    // ⚙️ 3D POSITION CONTROLS (EDIT HERE)
    // =========================================================================
    // 1. STAGE POSITION: Moves BOTH character and heart together
    //    Increase (e.g. 2.6, 2.9) to push right; Decrease (e.g. 1.8, 1.4) to pull left
    let MASCOT_STAGE_X = 2.4;

    // 2. CHARACTER ONLY (Mascot):
    //    startX: where mascot starts walking (Starts right after content = -3.7)
    //    endX: where mascot stops walking (Right in front of heart = 1.35)
    let startX = -3.7;
    let endX = 1.35;

    // 3. HEART ONLY: Stays at the right end in the same place
    let heartX = 2.4;

    // Director & Pacing State (Unhurried, realistic pacing)
    let storyLoopProgress = 0.05;
    let targetLoopProgress = 0.05;
    let currentAct = 0;
    let lockedAct = null;
    let lockTimer = null;
    let mouseX = 0, mouseY = 0, targetMouseX = 0, targetMouseY = 0;
    let clock = null; // Constructed safely inside init() after THREE availability guard
    let isUserPaused = false;
    let isHeroVisible = true;
    let isDocHidden = false;
    let animFrameId = null;
    let isLoopRunning = false;
    let isReducedMotion = false;
    let scratchVecTarget = null;
    let scratchVecPos = null;
    let dullHeartColor = null;
    let brightHeartColor = null;
    let brightHeartEmissive = null;

    const storyVars = {
        dropletCharge: 0.28,
        mascotWalkProgress: 0.0,
        heartAwaken: 0.0
    };

    // Helper: Soft Radial Glow Texture
    function createGlowTexture(hexColor) {
        const size = 256;
        const canvas = document.createElement('canvas');
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');
        const grad = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
        grad.addColorStop(0, hexColor);
        grad.addColorStop(0.4, hexColor + '88');
        grad.addColorStop(0.8, hexColor + '22');
        grad.addColorStop(1, hexColor + '00');
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, size, size);
        return new THREE.CanvasTexture(canvas);
    }

    // Helper: 4-Point Radiant Star Sparkle Texture (Twinkling Life Saver Glint)
    function createSparkleTexture() {
        const size = 128;
        const canvas = document.createElement('canvas');
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext('2d');
        const cx = size / 2, cy = size / 2;

        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, size / 2);
        grad.addColorStop(0, 'rgba(255, 255, 255, 1)');
        grad.addColorStop(0.2, 'rgba(255, 240, 220, 0.85)');
        grad.addColorStop(0.5, 'rgba(255, 120, 90, 0.3)');
        grad.addColorStop(1, 'rgba(255, 60, 40, 0)');
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, size, size);

        ctx.fillStyle = '#FFFFFF';
        ctx.beginPath();
        ctx.moveTo(cx, 6);
        ctx.quadraticCurveTo(cx, cy, size - 6, cy);
        ctx.quadraticCurveTo(cx, cy, cx, size - 6);
        ctx.quadraticCurveTo(cx, cy, 6, cy);
        ctx.quadraticCurveTo(cx, cy, cx, 6);
        ctx.closePath();
        ctx.fill();

        return new THREE.CanvasTexture(canvas);
    }

    // Helper: Mathematically Perfect 3D Blood Drop Lathe Geometry
    // Hemispherical bottom dome (C^1 continuous, dr/dy -> inf at pole) smoothly tapering to sleek top apex
    function createLifeSaverDropGeometry(radius = 0.25, height = 0.64) {
        const points = [];
        const segments = 48;
        for (let i = 0; i <= segments; i++) {
            const t = i / segments; // 0 at bottom pole, 1 at top tip
            const r = Math.max(0.001, radius * 2.598 * Math.sqrt(Math.max(0, t)) * (1.0 - t));
            const y = (t - 0.35) * height;
            points.push(new THREE.Vector2(r, y));
        }
        const geo = new THREE.LatheGeometry(points, 48);
        geo.computeVertexNormals();
        return geo;
    }

    // Helper: 3D Extruded Heart Geometry
    function createHeartGeometry(scale = 1.0, depth = 0.45) {
        const shape = new THREE.Shape();
        const x = 0, y = 0;
        shape.moveTo(x, y + 0.35);
        shape.bezierCurveTo(x, y + 0.35, x - 0.08, y, x - 0.45, y);
        shape.bezierCurveTo(x - 0.95, y, x - 0.95, y + 0.62, x - 0.95, y + 0.62);
        shape.bezierCurveTo(x - 0.95, y + 0.98, x - 0.58, y + 1.32, x, y + 1.65);
        shape.bezierCurveTo(x + 0.58, y + 1.32, x + 0.95, y + 0.98, x + 0.95, y + 0.62);
        shape.bezierCurveTo(x + 0.95, y + 0.62, x + 0.95, y, x + 0.45, y);
        shape.bezierCurveTo(x + 0.15, y, x, y + 0.35, x, y + 0.35);

        const extrudeSettings = {
            depth: depth,
            bevelEnabled: true,
            bevelSegments: 14,
            steps: 2,
            bevelSize: 0.16,
            bevelThickness: 0.16
        };
        const geo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
        geo.center();
        geo.rotateZ(Math.PI);
        geo.scale(scale, scale, scale);
        geo.computeVertexNormals();
        return geo;
    }

    function init() {
        heroSection = document.querySelector('.hero-viewport') || document.getElementById('home');
        const canvas = document.getElementById('hero-3d-canvas');
        if (!heroSection || !canvas) return;

        sceneFrame = document.getElementById('bg-canvas-container');
        if (!sceneFrame) return;
        const motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
        isReducedMotion = motionQuery.matches;
        isDocHidden = document.hidden;

        // Strict THREE availability guard before constructing any THREE object
        if (typeof THREE === 'undefined') {
            console.warn("Three.js library is not available. Showing static fallback.");
            showFallbackIllustration();
            return;
        }

        // Safe Clock construction after THREE guard
        clock = new THREE.Clock();
        scratchVecTarget = new THREE.Vector3();
        scratchVecPos = new THREE.Vector3();
        dullHeartColor = new THREE.Color(0x6E2424);
        brightHeartColor = new THREE.Color(0xD42B1E);
        brightHeartEmissive = new THREE.Color(0xCC1A0A);

        const width = sceneFrame.clientWidth || window.innerWidth;
        const height = sceneFrame.clientHeight || (window.innerHeight - 64);

        // 1. Scene & Warm Camera Setup
        scene = new THREE.Scene();
        scene.background = new THREE.Color(0xF8F9F5);
        scene.fog = new THREE.FogExp2(0xF8F9F5, 0.018);

        camera = new THREE.PerspectiveCamera(36, width / height, 0.1, 50);
        camera.position.set(0, 0.28, 8.2);
        camera.lookAt(0, 0.05, 0);

        // 2. Renderer with ACES Filmic Tone Mapping and WebGL error handling
        try {
            renderer = new THREE.WebGLRenderer({
                canvas: canvas,
                antialias: true,
                powerPreference: 'high-performance',
                alpha: true
            });
            renderer.setClearColor(0xF8F9F5, 1);
        } catch (err) {
            console.warn("WebGL initialization failed, showing fallback illustration.", err);
            showFallbackIllustration();
            return;
        }

        if (!renderer || !renderer.getContext()) {
            console.warn("WebGL context not available, showing fallback illustration.");
            showFallbackIllustration();
            return;
        }

        renderer.setSize(width, height);
        setHeroResolution(width, height);
        renderer.toneMapping = THREE.ACESFilmicToneMapping;
        renderer.toneMappingExposure = 1.05;

        // 3. Balanced Warm Studio Lighting
        const ambientLight = new THREE.AmbientLight(0xFFF7F0, 0.88);
        scene.add(ambientLight);

        const keyLight = new THREE.DirectionalLight(0xFFFAF5, 1.2);
        keyLight.position.set(5, 8, 7);
        scene.add(keyLight);

        const fillLight = new THREE.DirectionalLight(0xFFEDE4, 0.6);
        fillLight.position.set(-6, 4, 3);
        scene.add(fillLight);

        const rimLight = new THREE.DirectionalLight(0xFFDDD2, 0.75);
        rimLight.position.set(0, 4, -5);
        scene.add(rimLight);

        // 4. Main Stage Group (Holding Mascot, Heart, and Particles)
        stageGroup = new THREE.Group();
        scene.add(stageGroup);

        // Ground Contact Shadows
        const shadowTex = createGlowTexture('#DAC5BA');
        mascotShadowDisc = new THREE.Mesh(
            new THREE.PlaneGeometry(1.9, 1.05),
            new THREE.MeshBasicMaterial({ map: shadowTex, transparent: true, opacity: 0.40, depthWrite: false })
        );
        mascotShadowDisc.rotation.x = -Math.PI / 2;
        mascotShadowDisc.position.set(startX, -1.35, 0);
        stageGroup.add(mascotShadowDisc);

        heartShadowDisc = new THREE.Mesh(
            new THREE.PlaneGeometry(2.4, 1.25),
            new THREE.MeshBasicMaterial({ map: shadowTex, transparent: true, opacity: 0.36, depthWrite: false })
        );
        heartShadowDisc.rotation.x = -Math.PI / 2;
        heartShadowDisc.position.set(heartX, -1.35, 0);
        stageGroup.add(heartShadowDisc);

        // Build Scene Elements
        buildMascot();
        buildHeart();
        buildParticles();

        canvas.addEventListener('webglcontextlost', (event) => {
            event.preventDefault();
            pauseLoop();
            showFallbackIllustration();
        });
        canvas.addEventListener('webglcontextrestored', () => {
            sceneFrame.classList.remove('hero-3d-unavailable');
            updateLayout();
            resumeLoop();
        });

        // Responsive Stage Placement
        updateLayout();

        // Check initial reduced motion preference
        motionQuery.addEventListener('change', (e) => {
            isReducedMotion = e.matches;
            if (isReducedMotion) {
                renderStaticComposedScene();
            } else if (isHeroVisible && !isDocHidden && !isUserPaused) {
                resumeLoop();
            }
        });

        // Accessible Pause / Resume button
        const pauseBtn = document.getElementById('hero3dPauseBtn');
        if (pauseBtn) {
            pauseBtn.addEventListener('click', () => {
                isUserPaused = !isUserPaused;
                pauseBtn.setAttribute('aria-pressed', String(isUserPaused));
                const newLabel = isUserPaused ? 'Resume 3D animation' : 'Pause 3D animation';
                pauseBtn.setAttribute('title', newLabel);
                pauseBtn.setAttribute('aria-label', newLabel);
                const icon = pauseBtn.querySelector('i');
                if (icon) {
                    icon.className = isUserPaused ? 'fa-solid fa-play' : 'fa-solid fa-pause';
                }
                const srText = pauseBtn.querySelector('.sr-only');
                if (srText) srText.textContent = newLabel;

                if (isUserPaused) {
                    pauseLoop();
                } else {
                    resumeLoop();
                }
            });
        }

        // Pause when document is hidden
        document.addEventListener('visibilitychange', () => {
            isDocHidden = document.hidden;
            if (isDocHidden) {
                pauseLoop();
            } else if (!isUserPaused && isHeroVisible && !isReducedMotion) {
                resumeLoop();
            }
        });

        // Pause when hero viewport is off-screen
        if ('IntersectionObserver' in window) {
            const heroObserver = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    isHeroVisible = entry.isIntersecting;
                    if (isHeroVisible) {
                        if (!isUserPaused && !isDocHidden && !isReducedMotion) {
                            resumeLoop();
                        }
                    } else {
                        pauseLoop();
                    }
                });
            }, { threshold: 0.05 });
            heroObserver.observe(sceneFrame);
        }

        // Mouse Parallax & Interaction (passive, disabled during reduced motion)
        window.addEventListener('mousemove', (e) => {
            if (isReducedMotion) return;
            targetMouseX = (e.clientX / window.innerWidth) * 2 - 1;
            targetMouseY = -(e.clientY / window.innerHeight) * 2 + 1;
        }, { passive: true });

        // Resize Listener
        if ('ResizeObserver' in window) {
            new ResizeObserver(updateLayout).observe(sceneFrame);
        }
        window.addEventListener('resize', updateLayout, { passive: true });

        // Start render loop or static scene based on preference
        if (isReducedMotion) {
            renderStaticComposedScene();
        } else {
            resumeLoop();
        }
    }

    function setHeroResolution(width, height) {
        const pixelBudget = Math.sqrt(5000000 / Math.max(1, width * height));
        const ratio = window.devicePixelRatio || 1;
        renderer.setPixelRatio(mobileLayout.matches
            ? Math.min(1.5, ratio)
            : Math.min(2.5, Math.max(1.5, ratio), pixelBudget));
    }

    function updateLayout() {
        if (!sceneFrame || !renderer || !camera || !stageGroup) return;
        if (sceneFrame.classList.contains('hero-3d-unavailable')) return;

        const width = sceneFrame.clientWidth || window.innerWidth;
        const height = sceneFrame.clientHeight || (window.innerHeight - 64);

        camera.aspect = width / height;
        camera.updateProjectionMatrix();
        setHeroResolution(width, height);
        renderer.setSize(width, height, false);

        // Use the full mobile frame and keep the desktop scene to the right.
        const halfWidth = camera.position.z * Math.tan(camera.fov * Math.PI / 360) * camera.aspect;
        const stageX = halfWidth * .54 + MASCOT_STAGE_X - 2.4;
        if (mobileLayout.matches) {
            const mobileScale = Math.min(0.76, Math.max(0.64, halfWidth / 6.2));
            stageGroup.scale.setScalar(mobileScale);
            stageGroup.position.set(0.50, 0.06, 0);
        } else {
            const deskScale = Math.min(0.70, Math.max(0.46, halfWidth * 0.92 / 8.5));
            stageGroup.position.set(stageX, 0.04, 0);
            stageGroup.scale.setScalar(deskScale);
        }

        // Maintain configured heart position
        if (bigHeartGroup) {
            bigHeartGroup.position.x = heartX;
        }
        if (heartShadowDisc) {
            heartShadowDisc.position.x = heartX;
        }

        if (isReducedMotion) {
            renderStaticComposedScene();
        } else {
            renderFrame();
        }
    }

    // -------------------------------------------------------------------------
    // FALLBACK & LOOP LIFECYCLE MANAGEMENT
    // -------------------------------------------------------------------------
    function showFallbackIllustration() {
        sceneFrame.classList.remove('hero-3d-ready');
        sceneFrame.classList.add('hero-3d-unavailable');
    }

    function renderFrame() {
        renderer.render(scene, camera);
        sceneFrame.classList.add('hero-3d-ready');
    }

    function pauseLoop() {
        isLoopRunning = false;
        if (animFrameId) {
            cancelAnimationFrame(animFrameId);
            animFrameId = null;
        }
    }

    function resumeLoop() {
        if (isLoopRunning || isUserPaused || isDocHidden || !isHeroVisible || isReducedMotion ||
            sceneFrame.classList.contains('hero-3d-unavailable')) return;
        if (clock) {
            clock.getDelta(); // Flush delta so timeline doesn't leap forward
        }
        isLoopRunning = true;
        animate();
    }

    function renderStaticComposedScene() {
        pauseLoop();
        if (!renderer || !scene || !camera) return;

        storyVars.dropletCharge = 0.95;
        storyVars.mascotWalkProgress = 0.45;
        storyVars.heartAwaken = 0.85;

        const mascotX = startX + 0.45 * (stopPosition() - startX);
        poseMascot(0, 0, 1, 0);
        if (mascotGroup) {
            mascotGroup.position.set(mascotX, -0.32, 0);
            mascotGroup.rotation.set(0, .78, 0);
        }
        if (mascotShadowDisc) {
            mascotShadowDisc.position.set(mascotX, -1.35, 0);
        }
        if (heldDropletGroup) {
            heldDropletGroup.visible = true;
            heldDropletGroup.scale.setScalar(0.95 * .62);
        }
        if (bigHeartGroup) {
            bigHeartGroup.scale.setScalar(1.0);
            bigHeartGroup.position.y = -0.10;
            bigHeartGroup.rotation.y = -0.18;
        }
        if (bigHeartMesh) {
            if (brightHeartColor) bigHeartMesh.material.color.copy(brightHeartColor);
            if (brightHeartEmissive) bigHeartMesh.material.emissive.copy(brightHeartEmissive);
            bigHeartMesh.material.emissiveIntensity = 0.55;
        }
        if (bigHeartInnerCore) {
            bigHeartInnerCore.material.opacity = 0.35;
        }
        if (bigHeartAura) {
            bigHeartAura.material.opacity = 0.20;
        }

        camera.position.set(0, 0.28, 8.2);
        camera.lookAt(0, 0.05, 0);
        renderFrame();
    }

    // -------------------------------------------------------------------------
    // A. BUILD CUTE VIBRANT RED MASCOT CHARACTER
    // -------------------------------------------------------------------------
    function buildMascot() {
        mascotGroup = new THREE.Group();
        mascotGroup.position.set(startX, -0.32, 0);
        stageGroup.add(mascotGroup);

        // Body cross-sections traced from the source illustration, tip to base.
        const outline = [[8, 171, 172], [12, 160, 177], [20, 148, 178], [40, 125, 180], [60, 106, 189], [80, 88, 203], [100, 74, 218], [120, 62, 230], [140, 54, 238], [160, 50, 242], [180, 49, 243], [200, 51, 240], [220, 59, 233], [240, 73, 219], [250, 84, 208], [260, 101, 193], [267, 120, 177], [271, 145, 150]];
        const sides = 80, rings = 64;
        const vertices = [], uv = [], indices = [];
        let segment = 0;
        for (let j = 0; j <= rings; j++) {
            const v = j / rings, row = 8 + 263 * v;
            while (segment < outline.length - 2 && outline[segment + 1][0] < row) segment++;
            const [ya, la, ra] = outline[segment], [yb, lb, rb] = outline[segment + 1];
            const f = (row - ya) / (yb - ya);
            const left = la + (lb - la) * f, right = ra + (rb - ra) * f;
            const radius = (right - left) / 240;
            for (let i = 0; i <= sides; i++) {
                const u = i / sides, theta = (u * 2 - 1) * Math.PI;
                vertices.push(((left + right) / 2 - 146) / 120 + radius * Math.sin(theta),
                    (170 - row) / 120, radius * 0.87 * Math.cos(theta));
                uv.push(u, 1 - v);
                if (j < rings && i < sides) {
                    const a = j * (sides + 1) + i, b = a + sides + 1;
                    indices.push(a, b, a + 1, a + 1, b, b + 1);
                }
            }
        }
        const geometry = new THREE.BufferGeometry();
        geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
        geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
        geometry.setIndex(indices);
        geometry.computeVertexNormals();
        const skin = new THREE.MeshBasicMaterial({ color: 0xe27179, toneMapped: false, fog: false });
        mascotBodyMesh = new THREE.Mesh(geometry, skin);
        mascotGroup.add(mascotBodyMesh);
        new THREE.TextureLoader().load('data:image/png;base64,', texture => {
            texture.anisotropy = renderer.capabilities ? Math.min(8, renderer.capabilities.getMaxAnisotropy()) : 1;
            skin.map = texture; skin.color.setHex(0xffffff); skin.needsUpdate = true;
            if (isReducedMotion) renderStaticComposedScene();
        });
        const coral = new THREE.MeshBasicMaterial({ color: 0xdc6972, toneMapped: false });
        const sole = new THREE.MeshBasicMaterial({ color: 0xd4656d, toneMapped: false });
        function joint(rx, ry, rz, material = coral) {
            const shape = new THREE.SphereGeometry(1, 24, 18);
            const normals = shape.attributes.normal, shades = [];
            for (let i = 0; i < normals.count; i++) {
                const v = .95 + .055 * normals.getY(i) - .025 * normals.getX(i) + .035 * normals.getZ(i);
                shades.push(v, v, v);
            }
            shape.setAttribute('color', new THREE.Float32BufferAttribute(shades, 3));
            material.vertexColors = true;
            const m = new THREE.Mesh(shape, material);
            m.scale.set(rx, ry, rz); mascotGroup.add(m); return m;
        }
        for (const side of [-1, 1]) {
            limbs.push({
                side, shoulder: new THREE.Vector3(side * .69, -.19, .23),
                elbow: new THREE.Vector3(), palm: joint(.115, .088, .12),
                upper: joint(.102, 1, .102), forearm: joint(.092, 1, .092),
                hip: new THREE.Vector3(side * .32, -.65, 0), shin: joint(.13, 1, .13),
                foot: joint(.17, .12, .22, sole)
            });
        }
        // 8. Ultra-Glossy Luminous "Life Saver" Blood Drop Held in Hands
        heldDropletGroup = new THREE.Group();
        heldDropletGroup.position.set(0.58, -0.12, 0.45);
        mascotGroup.add(heldDropletGroup);

        // A. Outer Ruby Crystal Shell (Iconic clean blooddrop profile, ultra-glossy clearcoat)
        const lifeDropGeo = createLifeSaverDropGeometry(0.25, 0.64);
        const lifeDropMat = new THREE.MeshPhysicalMaterial({
            color: 0xFF1424,
            emissive: 0xDC2626,
            emissiveIntensity: 0.88,
            roughness: 0.04,
            metalness: 0.02,
            clearcoat: 1.0,
            clearcoatRoughness: 0.02,
            reflectivity: 1.0,
            transparent: true,
            opacity: 0.94
        });
        heldDropletMesh = new THREE.Mesh(lifeDropGeo, lifeDropMat);
        heldDropletGroup.add(heldDropletMesh);

        // B. Inner Golden-Warm Life Spark Core
        const coreGeo = createLifeSaverDropGeometry(0.12, 0.32);
        const coreMat = new THREE.MeshBasicMaterial({
            color: 0xFFF2A6,
            transparent: true,
            opacity: 0.92,
            blending: THREE.AdditiveBlending
        });
        heldDropletCore = new THREE.Mesh(coreGeo, coreMat);
        heldDropletCore.position.y = -0.02;
        heldDropletGroup.add(heldDropletCore);

        // C. Radiant Ambient Aura Halo
        const dropHaloTex = createGlowTexture('#FF3820');
        heldDropletHalo = new THREE.Sprite(
            new THREE.SpriteMaterial({
                map: dropHaloTex,
                transparent: true,
                opacity: 0.55,
                blending: THREE.AdditiveBlending
            })
        );
        heldDropletHalo.scale.set(1.15, 1.15, 1);
        heldDropletGroup.add(heldDropletHalo);

        // D. 4-Pointed Star Sparkle (Identifies as a gleaming, precious life saver)
        const sparkleTex = createSparkleTexture();
        heldDropletSparkle = new THREE.Sprite(
            new THREE.SpriteMaterial({
                map: sparkleTex,
                transparent: true,
                opacity: 0.85,
                blending: THREE.AdditiveBlending
            })
        );
        heldDropletSparkle.position.set(0.10, 0.08, 0.16);
        heldDropletSparkle.scale.set(0.48, 0.48, 1);
        heldDropletGroup.add(heldDropletSparkle);

        // E. Subtle Point Light illuminating hands and surroundings
        heldDropletLight = new THREE.PointLight(0xFF3322, 1.2, 2.0, 2);
        heldDropletLight.position.set(0, 0, 0.1);
        heldDropletGroup.add(heldDropletLight);
    }

    // -------------------------------------------------------------------------
    // B. BUILD LESS SHINY HEART (FROM DULL TO BRIGHT WITH HEART BEATS)
    // -------------------------------------------------------------------------

    function span(mesh, a, b) {
        mesh.position.subVectors(b, a);
        mesh.scale.y = mesh.position.length() / 2 + .06;
        mesh.quaternion.setFromUnitVectors(mesh.up, mesh.position.normalize());
        mesh.position.addVectors(a, b).multiplyScalar(.5);
    }
    // Estimate the visible rim of the widest body ring in camera space.
    // Keep the held drop just outside that rim as the mascot turns.
    function handCenterX(z) {
        mascotGroup.updateWorldMatrix(true, false);
        camera.updateMatrixWorld();
        const probe = scratchVecPos;
        function project(x, y, depth) {
            return probe.set(x, y, depth).applyMatrix4(mascotGroup.matrixWorld).project(camera).x;
        }
        let edge = -Infinity;
        for (let i = 0; i < 24; i++) {
            const a = i * Math.PI / 12;
            edge = Math.max(edge, project(.81 * Math.sin(a), -.08, .70 * Math.cos(a)));
        }
        const center = project(0, -.12, z);
        const dx = project(1, -.12, z) - center;
        const projectedRadius = Math.hypot(dx, project(0, -.12, z + 1) - center) * .155;
        return THREE.MathUtils.clamp((edge - center + projectedRadius +
            5 / Math.max(1, heroSection.clientWidth)) / Math.max(.001, dx), 0, 1.35);
    }

    function poseMascot(phase, walking, catchAmount, offer) {
        const cradleZ = .50 + offer * .045;
        const handX = handCenterX(cradleZ);
        for (const limb of limbs) {
            const side = limb.side, swing = Math.sin(phase) * side * walking;
            limb.foot.position.set(side * .32, -1.03 + Math.max(0, swing) * .18, .10 + swing * .29);
            limb.foot.rotation.x = -swing * .22;
            span(limb.shin, limb.hip, limb.foot.position);
            // The near-side palm receives the drop. The other arm rests at the hip.
            if (side > 0) {
                limb.palm.position.set(handX - .025, -.30 + offer * .055, cradleZ);
                limb.elbow.set(.78, -.37, .31);
            } else {
                limb.elbow.set(-.77, -.38, .26);
                limb.palm.position.set(-.74, -.49 + .035 * Math.sin(phase) * walking, .37);
            }
            span(limb.upper, limb.shoulder, limb.elbow);
            span(limb.forearm, limb.elbow, limb.palm.position);
        }
        heldDropletGroup.position.set(handX, -.14 + offer * .055 + 1.72 * (1 - catchAmount), cradleZ);
    }
    function stopPosition() {
        // Maximum pulsing heart radius plus the forward reach of both palms and the drop.
        return Math.min(endX, heartX - 3.65);
    }

    function buildHeart() {
        bigHeartGroup = new THREE.Group();
        bigHeartGroup.position.set(heartX, -0.10, -0.1);
        stageGroup.add(bigHeartGroup);

        // Less shiny, velvety/matte organic surface (NO plastic/glass clearcoat)
        const heartGeo = createHeartGeometry(1.22, 0.46);
        const heartMat = new THREE.MeshPhysicalMaterial({
            color: 0x6E2424,            // Starts in DULL, dormant wine-red
            emissive: 0x000000,         // Zero emissive initially (completely dull/asleep)
            emissiveIntensity: 0.0,
            roughness: 0.58,            // Organic matte velvety finish (NOT shiny!)
            metalness: 0.0,
            clearcoat: 0.0,             // No glossy clearcoat
            clearcoatRoughness: 0.5,
            transparent: true,
            opacity: 0.98
        });
        bigHeartMesh = new THREE.Mesh(heartGeo, heartMat);
        bigHeartGroup.add(bigHeartMesh);

        // Inner Luminescent Core (Appears as it transitions from dull to bright)
        const innerGeo = createHeartGeometry(0.84, 0.28);
        const innerMat = new THREE.MeshBasicMaterial({
            color: 0xFF3322,
            transparent: true,
            opacity: 0.0                // Dark inside initially
        });
        bigHeartInnerCore = new THREE.Mesh(innerGeo, innerMat);
        bigHeartGroup.add(bigHeartInnerCore);

        // Warm Soft Red Radial Aura Sprite (Emerges when awakened)
        const heartAuraTex = createGlowTexture('#E52515');
        bigHeartAura = new THREE.Sprite(
            new THREE.SpriteMaterial({
                map: heartAuraTex,
                transparent: true,
                opacity: 0.0,           // Dormant initially
                depthWrite: false
            })
        );
        bigHeartAura.scale.set(2.8, 2.8, 1);
        bigHeartAura.position.set(0, 0, -0.38);
        bigHeartGroup.add(bigHeartAura);

        // Expanding Crimson Pulse Ring
        const waveGeo = new THREE.RingGeometry(1.22, 1.28, 64);
        const waveMat = new THREE.MeshBasicMaterial({
            color: 0xD42B1E,
            side: THREE.DoubleSide,
            transparent: true,
            opacity: 0
        });
        const waveMesh = new THREE.Mesh(waveGeo, waveMat);
        waveMesh.position.z = -0.2;
        bigHeartGroup.add(waveMesh);
        heartPulseWaves.push({ mesh: waveMesh, offset: 0 });
    }

    // -------------------------------------------------------------------------
    // C. BUILD GENTLE, UNHURRIED PARTICLE SYSTEMS
    // -------------------------------------------------------------------------
    function buildParticles() {
        // 1. Gathering Embers (Gentle particles drifting in from all directions into mascot's hands)
        const gatherGeo = new THREE.SphereGeometry(0.048, 12, 12);
        const colors = [0xD42B1E, 0xFF5722, 0xFF8A65, 0xFFA726];

        for (let i = 0; i < 26; i++) {
            const mat = new THREE.MeshBasicMaterial({
                color: colors[i % colors.length],
                transparent: true,
                opacity: 0.7
            });
            const mesh = new THREE.Mesh(gatherGeo, mat);

            const angle = (i / 26) * Math.PI * 2 + Math.random() * 0.4;
            const radius = 2.0 + Math.random() * 2.8;
            const startPos = new THREE.Vector3(
                Math.cos(angle) * radius + startX,
                Math.sin(angle) * (radius * 0.6) + (Math.random() - 0.5) * 1.3,
                (Math.random() - 0.5) * 1.8
            );

            stageGroup.add(mesh);
            gatheringParticles.push({
                mesh,
                startPos,
                phaseOffset: Math.random(),
                swirlFreq: 1.1 + Math.random() * 1.2,
                baseScale: 0.5 + Math.random() * 0.5
            });
        }

        // 2. Radiating Warm Heart Sparks (Softly floating outward during cardiac beats)
        const radGeo = new THREE.SphereGeometry(0.042, 10, 10);
        for (let i = 0; i < 16; i++) {
            const mat = new THREE.MeshBasicMaterial({
                color: i % 2 === 0 ? 0xFF8A65 : 0xD42B1E,
                transparent: true,
                opacity: 0
            });
            const mesh = new THREE.Mesh(radGeo, mat);
            const angle = (i / 16) * Math.PI * 2 + (Math.random() - 0.5) * 0.2;
            const dir = new THREE.Vector3(
                Math.cos(angle),
                Math.sin(angle) * 0.85,
                (Math.random() - 0.5) * 0.5
            ).normalize();

            bigHeartGroup.add(mesh);
            radiatingParticles.push({
                mesh,
                dir,
                speed: 1.0 + Math.random() * 0.8,
                phaseOffset: i / 16,
                baseScale: 0.5 + Math.random() * 0.45
            });
        }
    }

    // -------------------------------------------------------------------------
    // D. STORY STATE MANAGEMENT
    // -------------------------------------------------------------------------
    window.setHeroStoryAct = function (actIdx) {
        currentAct = actIdx;
        lockedAct = actIdx;
        if (actIdx === 0) targetLoopProgress = 0.12;
        else if (actIdx === 1) targetLoopProgress = 0.50;
        else if (actIdx === 2) targetLoopProgress = 0.89;

        if (lockTimer) clearTimeout(lockTimer);
        lockTimer = setTimeout(() => {
            lockedAct = null;
        }, 5500);
    };

    // -------------------------------------------------------------------------
    // E. MAIN ANIMATION LOOP (Realistic, Unrushed Pacing)
    // -------------------------------------------------------------------------
    function animate() {
        if (!isLoopRunning || isUserPaused || isDocHidden || !isHeroVisible || isReducedMotion) {
            isLoopRunning = false;
            return;
        }
        animFrameId = requestAnimationFrame(animate);

        const delta = Math.min(clock.getDelta(), 0.05);
        const elapsed = clock.getElapsedTime();

        // Smooth mouse dampening for 3D parallax (disabled if reduced motion)
        if (!isReducedMotion) {
            mouseX += (targetMouseX - mouseX) * 0.04;
            mouseY += (targetMouseY - mouseY) * 0.04;
        }

        // Smooth, unhurried timeline advancement (natural ~25 second loop)
        const loopSpeed = 0.040;
        if (lockedAct === null) {
            storyLoopProgress = (storyLoopProgress + delta * loopSpeed) % 1.0;
            targetLoopProgress = storyLoopProgress;
            currentAct = storyLoopProgress < 0.30 ? 0 : (storyLoopProgress < 0.72 ? 1 : 2);
        } else {
            storyLoopProgress += (targetLoopProgress - storyLoopProgress) * 0.045;
        }

        // ---------------------------------------------------------------------
        // COMPUTE STORY VARIABLES (Smooth interpolation between acts)
        // ---------------------------------------------------------------------
        let targetDropScale = 1.0;
        let targetWalk = 0.0;
        let targetAwaken = 0.0;

        if (storyLoopProgress < 0.30) {
            // Act 0: Character catches blood particles, forming into a radiant life-saver droplet; heart is DULL
            const t = storyLoopProgress / 0.30;
            const smoothT = t * t * (3 - 2 * t);
            targetDropScale = 0.20 + smoothT * 0.85;
            targetWalk = 0.0;
            targetAwaken = 0.0; // Completely dull
        } else if (storyLoopProgress < 0.72) {
            // Act 1: After gathering blooddrop, starts moving from left end across screen to heart at right end
            const t = (storyLoopProgress - 0.30) / 0.42;
            const smoothT = t * t * (3 - 2 * t); // Smooth S-curve easing
            targetDropScale = 1.05;
            targetWalk = smoothT;
            targetAwaken = 0; // Gentle transition starting to warm up
        } else {
            // Act 2: Arrives at heart; heart awakens from dull to bright, beats with cardiac pulses
            const t = (storyLoopProgress - 0.72) / 0.28;
            targetDropScale = Math.max(0.35, 1.05 - t * 0.58);
            targetWalk = 1.0 - Math.max(0, (t - 0.76) / 0.24) * 0.95;
            targetAwaken = THREE.MathUtils.smoothstep(storyLoopProgress, .84, .855); // Full brightness!
        }

        storyVars.dropletCharge += (targetDropScale - storyVars.dropletCharge) * 0.06;
        const prevWalk = storyVars.mascotWalkProgress;
        storyVars.mascotWalkProgress += (targetWalk - storyVars.mascotWalkProgress) * 0.05;
        const walkVelocity = Math.abs(storyVars.mascotWalkProgress - prevWalk) * 60;
        storyVars.heartAwaken = targetAwaken;

        // ---------------------------------------------------------------------
        // MASCOT ANIMATION: NATURAL WALKING CADENCE & BIPEDAL KINEMATICS
        // ---------------------------------------------------------------------
        const mascotX = startX + storyVars.mascotWalkProgress * (stopPosition() - startX);
        const mascotZ = -0.15 + storyVars.mascotWalkProgress * 0.35;

        // Realistic stride cadence (~4.2 rad/s)
        const stepBlend = Math.min(1.0, walkVelocity * 18);
        const stepPhase = (mascotX - startX) * 9;

        // Natural vertical stepping bounce (bipedal center-of-mass trajectory)
        const walkStepBob = Math.abs(Math.sin(stepPhase)) * 0.08 * stepBlend;
        const idleBreath = Math.sin(elapsed * 1.8) * 0.025 * (1 - stepBlend * 0.7);

        mascotGroup.position.set(mascotX, -0.32 + walkStepBob + idleBreath, mascotZ);
        mascotShadowDisc.position.set(mascotX, -1.45, mascotZ);
        mascotShadowDisc.scale.setScalar(1.0 - walkStepBob * 0.8);

        const caught = THREE.MathUtils.smoothstep(storyLoopProgress, .125, .24);
        const offer = THREE.MathUtils.smoothstep(storyVars.mascotWalkProgress, .84, 1);
        mascotGroup.rotation.y = .51 + .18 * THREE.MathUtils.smoothstep(storyLoopProgress, .23, .35);
        mascotGroup.rotation.z = Math.cos(stepPhase) * .035 * stepBlend;
        poseMascot(stepPhase, stepBlend, caught, offer);
        const charge = storyVars.dropletCharge;
        const flight = THREE.MathUtils.smoothstep(storyLoopProgress, .75, .84);
        // Interpolate in stage coordinates so the released drop can reach the heart.
        if (flight > 0) {
            mascotGroup.updateMatrix();
            const point = scratchVecTarget.copy(heldDropletGroup.position).applyMatrix4(mascotGroup.matrix);
            point.x += (heartX - point.x) * flight;
            point.y += (-.10 - point.y) * flight + .24 * Math.sin(Math.PI * flight);
            point.z += (.18 - point.z) * flight;
            stageGroup.localToWorld(point);
            heldDropletGroup.position.copy(mascotGroup.worldToLocal(point));
        }
        heldDropletGroup.visible = flight < 1;
        const absorb = THREE.MathUtils.smoothstep(flight, .70, 1);
        heldDropletGroup.scale.setScalar(Math.max(.001, charge * .62 * (1 - absorb)));

        // Smooth rotation
        heldDropletMesh.rotation.y = elapsed * 0.85;

        // Shiny, bright, living light pulsations (Life Saver effect)
        const shimmer = Math.sin(elapsed * 4.2) * 0.15;
        const pulseGlow = 0.88 + charge * 0.45 + shimmer;
        heldDropletMesh.material.emissiveIntensity = pulseGlow;

        // Inner glowing warm life core
        if (heldDropletCore) {
            heldDropletCore.rotation.y = -elapsed * 1.2;
            const coreScale = 0.92 + Math.sin(elapsed * 4.8) * 0.12;
            heldDropletCore.scale.set(coreScale, coreScale, coreScale);
            heldDropletCore.material.opacity = (0.55 + charge * 0.42) * (0.85 + shimmer * 0.4);
        }

        // Ambient radiant halo
        if (heldDropletHalo) {
            heldDropletHalo.material.opacity = 0.35 + charge * 0.4 + shimmer * 0.25;
            const haloS = 1.05 + Math.sin(elapsed * 2.8) * 0.10;
            heldDropletHalo.scale.set(haloS, haloS, 1);
        }

        // 4-point star sparkle (Life Saver specular twinkle)
        if (heldDropletSparkle) {
            const twinkle = Math.pow(Math.max(0, Math.sin(elapsed * 3.4)), 3.0);
            heldDropletSparkle.material.opacity = Math.max(0, (charge - 0.35) / 0.65) * (0.35 + twinkle * 0.65);
            heldDropletSparkle.material.rotation = elapsed * 0.5;
            const starS = 0.44 + twinkle * 0.22;
            heldDropletSparkle.scale.set(starS, starS, 1);
        }

        // Point light intensity following droplet charge
        if (heldDropletLight) {
            heldDropletLight.intensity = (0.5 + charge * 1.2) * (0.9 + shimmer * 0.3);
        }

        // ---------------------------------------------------------------------
        // GATHERING PARTICLES ANIMATION (Flowing smoothly into mascot's hands)
        // ---------------------------------------------------------------------
        if (scratchVecTarget) {
            // Target the EXACT center of the held droplet in world space
            mascotGroup.updateMatrix();
            scratchVecTarget.copy(heldDropletGroup.position).applyMatrix4(mascotGroup.matrix);
        }
        const gatherIntensity = currentAct === 0 ? 0.95 : (currentAct === 1 ? 0.3 : 0.12);

        gatheringParticles.forEach(p => {
            const u = (elapsed * 0.36 + p.phaseOffset) % 1.0;
            const easeU = u * u * (3 - 2 * u);

            if (scratchVecPos && scratchVecTarget) {
                scratchVecPos.lerpVectors(p.startPos, scratchVecTarget, easeU);
                const arc = Math.sin(easeU * Math.PI) * 0.45;
                scratchVecPos.y += Math.sin(elapsed * p.swirlFreq + p.phaseOffset * 8) * arc * 0.35;
                scratchVecPos.z += Math.cos(elapsed * p.swirlFreq + p.phaseOffset * 6) * arc * 0.25;
                p.mesh.position.copy(scratchVecPos);
            }
            const fade = Math.sin(easeU * Math.PI);
            p.mesh.material.opacity = fade * 0.85 * gatherIntensity;
            p.mesh.scale.setScalar(p.baseScale * (1.1 - easeU * 0.4));
        });

        // ---------------------------------------------------------------------
        // FROM DULL TO BRIGHT WITH AUTHENTIC "LUB-DUB" CARDIAC BEATS
        // -------------------------------------------------------------------------
        const awaken = storyVars.heartAwaken;

        // Human Resting Heartbeat waveform: ~60 BPM (1 cycle = 1.0s)
        const beatCycle = Math.max(0, (storyLoopProgress - .84) * 25) % 1;
        // Phase 1: "Lub" (Systolic ventricular contraction) at t = 0.12
        const lub = Math.exp(-Math.pow((beatCycle - 0.12) * 16, 2));
        // Phase 2: "Dub" (Aortic/pulmonary valve recoil) at t = 0.32
        const dub = Math.exp(-Math.pow((beatCycle - 0.32) * 18, 2)) * 0.60;
        // Diastolic resting pause follows for the remainder of the cycle (t = 0.40 to 1.0)
        // Cardiac beats activate ONLY as heart turns bright (awaken > 0.25)
        const cardiacImpulse = (lub + dub) * Math.max(0, (awaken - 0.25) / 0.75);

        // Heart movement & scale: Still slow dormant breath when dull; lively pulse when bright
        const idleHeartBreath = 0;
        const heartScale = 1.0 + idleHeartBreath + cardiacImpulse * 0.14;
        bigHeartGroup.scale.setScalar(heartScale);
        bigHeartGroup.position.y = -0.10 + Math.sin(elapsed * 1.4) * 0.02;
        bigHeartGroup.rotation.y = -0.18 + Math.sin(elapsed * 0.75) * 0.04;

        // COLOR & LUMINESCENCE: FROM DULL TO BRIGHT
        // Dull state: Muted dark rose-wine (0x6E2424) with NO emissive
        // Bright state: Vibrant warm living red (0xD42B1E) with warm glowing emissive
        if (dullHeartColor && brightHeartColor) {
            bigHeartMesh.material.color.copy(dullHeartColor).lerp(brightHeartColor, awaken);
        }
        if (brightHeartEmissive) {
            bigHeartMesh.material.emissive.copy(brightHeartEmissive);
        }
        bigHeartMesh.material.emissiveIntensity = awaken * 0.42 + cardiacImpulse * 0.48;

        // Inner Luminescent Core (Appears as it brightens)
        bigHeartInnerCore.material.opacity = awaken * 0.32 + cardiacImpulse * 0.22;
        bigHeartInnerCore.scale.setScalar(0.88 + cardiacImpulse * 0.12);

        // Soft Radial Aura (Glows when bright & pulses with beats)
        bigHeartAura.material.opacity = awaken * 0.22 + cardiacImpulse * 0.16;
        const auraSize = 3.2 + awaken * 0.8 + cardiacImpulse * 0.4;
        bigHeartAura.scale.set(auraSize, auraSize, 1);

        // Expanding Crimson Pulse Ring (Triggered during cardiac beat)
        heartPulseWaves.forEach(w => {
            const cycle = (elapsed * 0.5 + w.offset) % 1.0;
            const s = 1.0 + cycle * 1.5;
            w.mesh.scale.set(s, s, 1);
            w.mesh.material.opacity = (1.0 - cycle) * 0.25 * Math.max(0, (awaken - 0.3) / 0.7);
        });

        // Radiating warm sparks drifting outward from the beating heart
        radiatingParticles.forEach(rp => {
            const cycle = (elapsed * 0.4 + rp.phaseOffset) % 1.0;
            const dist = 0.65 + cycle * 2.1;
            rp.mesh.position.copy(rp.dir).multiplyScalar(dist);
            const fade = Math.sin(cycle * Math.PI);
            rp.mesh.material.opacity = fade * 0.65 * Math.max(0, (awaken - 0.35) / 0.65);
            rp.mesh.scale.setScalar(rp.baseScale * (1.0 - cycle * 0.35));
        });

        // Subtle 3D camera parallax following user mouse
        camera.position.x += ((mobileLayout.matches ? 0 : mouseX * 0.35) - camera.position.x) * 0.04;
        camera.position.y += (0.28 + (mobileLayout.matches ? 0 : mouseY * 0.18) - camera.position.y) * 0.04;
        camera.lookAt(0, 0.05, 0);

        renderFrame();
    }

    // Initialize when DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

    // -------------------------------------------------------------------------
    // 🛠️ LIVE DEV TOOLS (Test positions in browser console)
    // -------------------------------------------------------------------------
    window.setHeroStageX = function (val) {
        MASCOT_STAGE_X = val;
        if (stageGroup) stageGroup.position.x = val;
        console.log(`[Hero 3D] Stage position set to: ${val}`);
    };

    window.setHeroCharacterX = function (start, end) {
        const oldStart = startX;
        if (start !== undefined) startX = start;
        if (end !== undefined) endX = end;
        const diff = startX - oldStart;
        if (gatheringParticles && diff !== 0) {
            gatheringParticles.forEach(p => {
                if (p.startPos) p.startPos.x += diff;
            });
        }
        console.log(`[Hero 3D] Character bounds set to: startX = ${startX}, endX = ${endX}`);
    };

    window.setHeroHeartX = function (val) {
        heartX = val;
        if (bigHeartGroup) bigHeartGroup.position.x = val;
        if (heartShadowDisc) heartShadowDisc.position.x = val;
        console.log(`[Hero 3D] Heart position set to: ${val}`);
    };
})();